:false,"supplements":[]},{"name":"Brioche Perdue Caramel","description":"Brioche perdue, glace vanille, caramel, éclats de noisettes","price":8.9,"category":"Desserts","emoji":"🍽️","photo_url":"/menu/brioche-perdue-caramel.jpg","is_popular":false,"sort_order":39,"is_menu":false,"supplements":[]},{"name":"Brioche Perdue Chocolat","description":"Brioche perdue, chantilly, chocolat, fruits rouges","price":8.9,"category":"Desserts","emoji":"🍽️","photo_url":"/menu/brioche-perdue-chocolat.jpg","is_popular":false,"sort_order":40,"is_menu":false,"supplements":[]},{"name":"Churros","description":"Churros maison, sucre cannelle, sauce chocolat","price":4.9,"category":"Desserts","emoji":"🍽️","photo_url":"/menu/churros.jpg","is_popular":false,"sort_order":41,"is_menu":false,"supplements":[]},{"name":"Mojito Violette","description":"Citron vert, menthe fraîche, sirop de violette","price":5.5,"category":"Mojitos & Boissons","emoji":"🍽️","photo_url":"/menu/mojito-violette.jpg","is_popular":false,"sort_order":42,"is_menu":false,"supplements":[]},{"name":"Mojito Passion","description":"Citron vert, menthe fraîche, fruit de la passion","price":5.5,"category":"Mojitos & Boissons","emoji":"🍽️","photo_url":"/menu/mojito-passion.jpg","is_popular":false,"sort_order":43,"is_menu":false,"supplements":[]},{"name":"Mojito Cerise","description":"Citron vert, menthe fraîche, sirop de cerise","price":5.5,"category":"Mojitos & Boissons","emoji":"🍽️","photo_url":"/menu/mojito-cerise.jpg","is_popular":false,"sort_order":44,"is_menu":false,"supplements":[]},{"name":"Mojito Kiwi","description":"Citron vert, menthe fraîche, kiwi","price":5.5,"category":"Mojitos & Boissons","emoji":"🍽️","photo_url":"/menu/mojito-kiwi.jpg","is_popular":false,"sort_order":45,"is_menu":false,"supplements":[]},{"name":"Mojito Classique","description":"Citron vert, menthe fraîche, sucre de canne","price":5.5,"category":"Mojitos & Boissons","emoji":"🍽️","photo_url":"/menu/mojito-classique.jpg","is_popular":false,"sort_order":46,"is_menu":false,"supplements":[]},{"name":"Thé Glacé Maison","description":"Thé glacé maison, menthe fraîche","price":5.5,"category":"Mojitos & Boissons","emoji":"🍽️","photo_url":"/menu/the-glace.jpg","is_popular":false,"sort_order":47,"is_menu":false,"supplements":[]},{"name":"Menu Midi","description":"Burger + frites — formule valable de 12h à 15h, du lundi au vendredi · Au choix : Végé, Fried Chicken, Cheese Burger, Smash Bao, Chicken Thaï · Boisson au choix : +1.50€ · Cocktail au choix : +3.50€","price":15.9,"category":"Formules","emoji":"🍽️","photo_url":"/menu/menu-midi.jpg","is_popular":true,"sort_order":48,"is_menu":true,"supplements":[{"name":"Bao Végé","price":0,"group":"Burger","required":true},{"name":"Fried Chicken / Spicy","price":0,"group":"Burger","required":true},{"name":"Smash Cheese","price":0,"group":"Burger","required":true},{"name":"Smash Bao Burger","price":0,"group":"Burger","required":true},{"name":"Chicken Thaï","price":0,"group":"Burger","required":true}]},{"name":"Menu Enfant","description":"Burger ou Nuggets · + 1 frite · + 1 boisson · + 1 compote ou 1 boule de glace","price":9.9,"category":"Formules","emoji":"🍽️","photo_url":"/menu/menu-enfant.jpg","is_popular":true,"sort_order":49,"is_menu":true,"supplements":[]}]$json$::jsonb;
  v_order jsonb := $json$["Formules","Bao Créations","Smash Bao","Smash Burger","Asian Fusion","Starters","Starters Signatures","Wings","Sides","Desserts","Mojitos & Boissons"]$json$::jsonb;
  v_group uuid;
  r record;
  it jsonb;
begin
  select group_id into v_group from restaurants where slug = 'baoma';

  for r in
    select id, slug, name from restaurants
     where slug like 'baoma%' or (v_group is not null and group_id = v_group)
  loop
    raise notice 'Carte synchronisée : % (%)', r.name, r.slug;

    for it in select * from jsonb_array_elements(v_canon) loop
      update menu_items set
             description = it->>'description',
             price       = (it->>'price')::numeric,
             emoji       = it->>'emoji',
             photo_url   = it->>'photo_url',
             is_popular  = (it->>'is_popular')::boolean,
             sort_order  = (it->>'sort_order')::int,
             is_menu     = (it->>'is_menu')::boolean,
             supplements = it->'supplements',
             available   = true
       where restaurant_id = r.id and name = it->>'name' and category = it->>'category';

      if not found then
        insert into menu_items (restaurant_id, name, description, price, category, emoji,
                                photo_url, is_popular, available, sort_order, is_menu, supplements)
        values (r.id, it->>'name', it->>'description', (it->>'price')::numeric, it->>'category',
                it->>'emoji', it->>'photo_url', (it->>'is_popular')::boolean, true,
                (it->>'sort_order')::int, (it->>'is_menu')::boolean, it->'supplements');
      end if;
    end loop;

    update menu_items m set available = false
     where m.restaurant_id = r.id and m.available = true
       and not exists (
         select 1 from jsonb_array_elements(v_canon) c
          where c->>'name' = m.name and c->>'category' = m.category);

    insert into restaurant_settings (restaurant_id, category_order)
    values (r.id, v_order)
    on conflict (restaurant_id) do update set category_order = excluded.category_order;
  end loop;
end
$fn$;

select sync_baoma_menu();

-- Vérification : comptes Baoma, plats actifs et nombre d'options.
select r.slug, count(*) filter (where m.available) as plats_actifs,
       count(*) filter (where not m.available) as plats_desactives
  from restaurants r join menu_items m on m.restaurant_id = r.id
 where r.slug like 'baoma%'
    or r.group_id = (select group_id from restaurants where slug = 'baoma' and group_id is not null)
 group by r.slug order by r.slug;
